INSERT INTO "gymbro".schema_migrations(version) VALUES ('20261025_exercise_guides') ON CONFLICT DO NOTHING;
COMMIT;
SELECT count(*) AS ejercicios, count(description) AS con_descripcion, count(video_url) AS con_video FROM gymbro.exercises WHERE created_by_user_id IS NULL AND deleted_at IS NULL;
